// Talulah, the Fighter (enemy_3002_ftrtal, PRTS 斗士塔露拉) and the Infected Patrol Captains (enemy_1107_uoffcr, _2)
// and the Ursus Raiders (enemy_1111_ucommd, _2).
// The Fighter is a NEUTRAL route actor (`_sideTypeIndex` 2, like the Mark of Epoch; `NeutralTag` mark_neutral[effect]:
// BLOCK_FREE and sleep immunity). She walks her route, is not counted, costs nothing when she exits and, when she is
// killed, `upeople_t` (ON_OWNER_KILLED: ModifyLifePoint by `dead.value`) takes 2 life points. Her abilities are the
// boss Talulah's with her own values: a ×1 Arts projectile (no blocked mode), Burning Breath on one hostile enemy in
// her attack range that is not already burning (200/s rising to 400/s over 20 s, 30.5 s), Stellar Corona at a 10000 s
// cooldown (never cast in a stage), and below half HP DEF and RES +50% with the faster [Half] Burning Breath. Her
// selectors skip units tagged tap_roadblock.
// No ordinary enemy selects her: the Patrol Captains' and Ursus Raiders' ranged attack is the one that does (its trigger
// selects only units carrying mark_neutral[effect]; PRTS: radius 1.2, ground only). They otherwise strike their blocker.
// Every component reachable from the retained abilities, the templates, the projectiles and the clip clocks are
// pinned below with local references reduced to null/local, as in enemy-talulah-features.js.
import fighterClocks from "../../data/arkpedia-talulah-fighter-animations.json" with{type:"json"};
import captainClocks from "../../data/arkpedia-patrol-captain-animations.json" with{type:"json"};
import {sameOutcomeValue as same} from "./enemy-outcome-contracts.js";
export const isTalulahFighter=r=>r?.prefabKey==="enemy_3002_ftrtal";
export const isPatrolCaptain=r=>/^enemy_(1107_uoffcr|1111_ucommd)(_2)?$/.test(r?.prefabKey??"");
export const NEUTRAL_MARK="mark_neutral[effect]";
export const FIGHTER_BREATH_TEXT="Applies [Burning Breath] to an enemy within attack range (Deals increasing True damage each second, but can be <$ba.buffres>Resisted</>)";
export const FIGHTER_LIFE_TEXT="Does not deduct Life Points when entering the enemy Incursion Point, but will instead deduct Life Points upon dying";
export const CAPTAIN_TEXT="Can use long-ranged weapons to attack <Ursus Civilians> and <Talulah, the Fighter>";
